<?php
class Session { public static function start(): void { if (session_status() === PHP_SESSION_NONE) session_start(); } public static function get(string $key, mixed $default=null): mixed { self::start(); return $_SESSION[$key] ?? $default; } public static function put(string $key, mixed $value): void { self::start(); $_SESSION[$key] = $value; } public static function forget(string $key): void { self::start(); unset($_SESSION[$key]); } }
